// Properties that force layout
const element = document.getElementById('myElement');

// These trigger layout:
element.offsetWidth;      // Forces layout
element.offsetHeight;     // Forces layout
element.offsetLeft;       // Forces layout
element.offsetTop;        // Forces layout
element.scrollWidth;      // Forces layout
element.scrollHeight;     // Forces layout
element.clientWidth;      // Forces layout
element.clientHeight;     // Forces layout

// These also trigger layout:
getComputedStyle(element).width;
getComputedStyle(element).height;
getComputedStyle(element).left;
getComputedStyle(element).top;

// Rect is particularly expensive
element.getBoundingClientRect(); // Forces layout

// Safe properties (don't force layout):
element.style.width;         // Just reads inline style
element.getAttribute('width'); // Just reads attribute

// Bad: Layout thrashing
function animateElements(elements) {
  for (const element of elements) {
    // Read layout (forces layout)
    const width = element.offsetWidth;

    // Modify DOM
    element.style.width = width + 10 + 'px';

    // Read layout again (forces layout again)
    const newWidth = element.offsetWidth;

    // Modify DOM again
    element.style.marginLeft = newWidth + 'px';
  }
}
// N elements = N × 2 layout calculations
// Extremely slow for many elements

// Good: Batch reads and writes
function animateElementsOptimized(elements) {
  // Phase 1: Read all layout properties
  const widths = elements.map(el => el.offsetWidth);

  // Phase 2: Write all DOM modifications
  elements.forEach((element, index) => {
    element.style.width = widths[index] + 10 + 'px';
    element.style.marginLeft = widths[index] + 10 + 'px';
  });

  // Phase 3: Read again if needed
  const newWidths = elements.map(el => el.offsetWidth);
}
// 1 layout calculation (initial reads)
// 1 layout calculation (final reads)
// Much faster for many elements

function smoothAnimation(element) {
  let width = element.offsetWidth;

  function animate() {
    // Read layout at start of frame
    const currentWidth = element.offsetWidth;

    requestAnimationFrame(() => {
      // Modify DOM during frame
      element.style.width = currentWidth + 1 + 'px';

      requestAnimationFrame(animate);
    });
  }

  animate();
}

// Or use the pattern of reading outside rAF
function optimizedAnimation(element) {
  let width = element.offsetWidth;

  function animate() {
    requestAnimationFrame(() => {
      // Write only inside rAF
      element.style.width = width + 1 + 'px';
      width += 1;

      requestAnimationFrame(animate);
    });
  }

  animate();
}
